/* ===== орбитали s, p, d в системе координат таблицы ===== */
const ORB=[{id:'s',h:'s'},{id:'px',h:'p<sub>x</sub>'},{id:'py',h:'p<sub>y</sub>'},{id:'pz',h:'p<sub>z</sub>'},
  {id:'dz2',h:'d<sub>z²</sub>'},{id:'dx2y2',h:'d<sub>x²−y²</sub>'},{id:'dxy',h:'d<sub>xy</sub>'},{id:'dxz',h:'d<sub>xz</sub>'},{id:'dyz',h:'d<sub>yz</sub>'}];
const s6=1/Math.sqrt(6),s2=1/Math.SQRT2;
const DB=[[[-s6,0,0],[0,-s6,0],[0,0,2*s6]],[[s2,0,0],[0,-s2,0],[0,0,0]],[[0,.5*Math.SQRT2,0],[.5*Math.SQRT2,0,0],[0,0,0]].map(r=>r.map(x=>x*s2*Math.SQRT2)),
  [[0,0,s2],[0,0,0],[s2,0,0]],[[0,0,0],[0,0,s2],[0,s2,0]]];
DB[2]=[[0,s2,0],[s2,0,0],[0,0,0]];
function frob(a,b){let s=0;for(let i=0;i<3;i++)for(let j=0;j<3;j++)s+=a[i][j]*b[i][j];return s}
function rep9(Mt){const D=Array.from({length:9},()=>new Array(9).fill(0));D[0][0]=1;
  for(let i=0;i<3;i++)for(let j=0;j<3;j++)D[1+i][1+j]=Mt[i][j];
  for(let j=0;j<5;j++){const B=mm(mm(Mt,DB[j]),tp(Mt));for(let i=0;i<5;i++)D[4+i][4+j]=frob(DB[i],B)}return D}
function orbImage(M,B,i){const D=rep9(mm(mm(tp(B.Q),M),B.Q));return D.map(r=>r[i])}
/* ===== счётчики Γ ===== */
function fixedAtoms(M,atoms){return atoms.map((a,i)=>{const q=mv(M,a.p);return Math.hypot(q[0]-a.p[0],q[1]-a.p[1],q[2]-a.p[2])<2e-3?i:-1}).filter(i=>i>=0)}
